// Original LZMA / LZMA2 encoder implementation.
// Produces streams decodable by any standard LZMA decoder.
#include "Lzma.h"
#include <algorithm>

namespace {

const uint32_t kNumBitModelTotalBits = 11;
const uint32_t kBitModelTotal = 1u << kNumBitModelTotalBits;
const uint32_t kMoveBits = 5;
const uint32_t kProbInit = kBitModelTotal / 2; // 1024
const uint32_t kTopValue = 1u << 24;

const int kNumStates = 12;
const uint32_t kMatchMinLen = 2;
const uint32_t kNumLenSymbols = 16; // 2 low + 8 mid + 256 high, lengths 2..271
const uint32_t kMatchMaxLen = kMatchMinLen + kNumLenSymbols - 1; // 273... see LenCoder
const uint32_t kNumPosSlotBits = 6;
const uint32_t kNumLenToPosStates = 4;
const uint32_t kNumAlignBits = 4;
const uint32_t kAlignTableSize = 1u << kNumAlignBits;
const uint32_t kEndPosModelIndex = 14;
const uint32_t kNumFullDistances = 1u << (kEndPosModelIndex >> 1); // 128
const uint32_t kNumSpecPos = kNumFullDistances + (1u << (kNumPosSlotBits + 1)) - 2; // 241
const uint32_t kNumLitContextBitsMax = 8;
const uint32_t kNumPosBitsMax = 4;

// probability models
struct ProbModels {
  std::vector<uint16_t> lit; // (0x300 << (lc+lp)) entries
  uint16_t isMatch[kNumStates][1 << kNumPosBitsMax];
  uint16_t isRep[kNumStates];
  uint16_t isRepG0[kNumStates];
  uint16_t isRepG1[kNumStates];
  uint16_t isRepG2[kNumStates];
  uint16_t isRep0Long[kNumStates][1 << kNumPosBitsMax];
  uint16_t posSlot[kNumLenToPosStates][1 << kNumPosSlotBits];
  uint16_t specPos[kNumSpecPos];
  uint16_t posAlign[kAlignTableSize];

  void InitProbs(uint16_t* p, size_t n) { for (size_t i = 0; i < n; i++) p[i] = (uint16_t)kProbInit; }

  void Init(int lc, int lp) {
    lit.assign((size_t)0x300 << (lc + lp), (uint16_t)kProbInit);
    InitProbs(&isMatch[0][0], kNumStates * (1 << kNumPosBitsMax));
    InitProbs(isRep, kNumStates);
    InitProbs(isRepG0, kNumStates);
    InitProbs(isRepG1, kNumStates);
    InitProbs(isRepG2, kNumStates);
    InitProbs(&isRep0Long[0][0], kNumStates * (1 << kNumPosBitsMax));
    InitProbs(&posSlot[0][0], kNumLenToPosStates * (1 << kNumPosSlotBits));
    InitProbs(specPos, kNumSpecPos);
    InitProbs(posAlign, kAlignTableSize);
  }
};

struct LenProbs {
  uint16_t choice;
  uint16_t choice2;
  uint16_t low[1 << kNumPosBitsMax][8];
  uint16_t mid[1 << kNumPosBitsMax][8];
  uint16_t high[256];
  void Init() {
    choice = choice2 = (uint16_t)kProbInit;
    for (int i = 0; i < (1 << kNumPosBitsMax); i++)
      for (int j = 0; j < 8; j++) low[i][j] = mid[i][j] = (uint16_t)kProbInit;
    for (int i = 0; i < 256; i++) high[i] = (uint16_t)kProbInit;
  }
};

// range encoder with cache/cacheSize carry scheme
struct RangeEnc {
  ByteBuf buf;
  uint64_t low;
  uint32_t range;
  Byte cache;
  uint64_t cacheSize;

  void Init() {
    buf.clear();
    buf.reserve(1 << 16);
    low = 0;
    range = 0xFFFFFFFFu;
    cache = 0;
    cacheSize = 1;
  }
  void ShiftLow() {
    if ((uint32_t)low < 0xFF000000u || (uint32_t)(low >> 32) != 0) {
      Byte carry = (Byte)(low >> 32);
      Byte temp = cache;
      do {
        buf.push_back((Byte)(temp + carry));
        temp = 0xFF;
      } while (--cacheSize != 0);
      cache = (Byte)(low >> 24);
    }
    cacheSize++;
    low = (uint64_t)(uint32_t)low << 8;
  }
  void EncodeBit(uint16_t& prob, uint32_t bit) {
    uint32_t bound = (range >> kNumBitModelTotalBits) * prob;
    if (bit == 0) {
      range = bound;
      prob = (uint16_t)(prob + ((kBitModelTotal - prob) >> kMoveBits));
    } else {
      low += bound;
      range -= bound;
      prob = (uint16_t)(prob - (prob >> kMoveBits));
    }
    if (range < kTopValue) {
      range <<= 8;
      ShiftLow();
    }
  }
  void EncodeDirect(uint32_t v, int numBits) {
    for (int i = numBits - 1; i >= 0; i--) {
      range >>= 1;
      if ((v >> i) & 1) low += range;
      if (range < kTopValue) {
        range <<= 8;
        ShiftLow();
      }
    }
  }
  void EncodeTree(uint16_t* probs, int numBits, uint32_t sym) {
    uint32_t m = 1;
    for (int i = numBits - 1; i >= 0; i--) {
      uint32_t bit = (sym >> i) & 1;
      EncodeBit(probs[m], bit);
      m = (m << 1) | bit;
    }
  }
  void EncodeTreeRev(uint16_t* probs, int numBits, uint32_t sym) {
    uint32_t m = 1;
    for (int i = 0; i < numBits; i++) {
      uint32_t bit = (sym >> i) & 1;
      EncodeBit(probs[m], bit);
      m = (m << 1) | bit;
    }
  }
  void Flush() {
    for (int i = 0; i < 5; i++) ShiftLow();
  }
};

static inline uint32_t GetLenToPosState(uint32_t len) {
  len -= kMatchMinLen;
  return len < kNumLenToPosStates ? len : kNumLenToPosStates - 1;
}

static inline uint32_t GetPosSlot(uint32_t dist) {
  // index of most significant bit of dist (dist >= 1)
  uint32_t i = 31;
#if defined(__GNUC__)
  i = 31u - (uint32_t)__builtin_clz(dist);
#else
  while (!((dist >> i) & 1)) i--;
#endif
  return i;
}

struct MatchFinder {
  const Byte* data = nullptr;
  size_t size = 0;
  uint32_t window = 0;
  std::vector<int32_t> head;
  std::vector<int32_t> prev;
  size_t cur = 0; // next position to insert

  static uint32_t Hash4(const Byte* p) {
    return (Get32(p) * 2654435761u) >> 8;
  }

  void Init(const Byte* d, size_t n, uint32_t dictSize) {
    data = d;
    size = n;
    window = dictSize;
    if (window > n) window = (uint32_t)n;
    head.assign(1u << 24, -1);
    prev.assign(n ? n : 1, -1);
    cur = 0;
  }

  void Insert(size_t pos) {
    if (pos + 4 <= size) {
      uint32_t h = Hash4(data + pos);
      prev[pos] = head[h];
      head[h] = (int32_t)pos;
    } else {
      prev[pos] = -1;
    }
  }

  // Find longest match at pos (pos already inserted). Returns len; *distOut = dist+1.
  uint32_t Find(size_t pos, uint32_t maxLen, uint32_t depth, uint32_t* distOut) {
    uint32_t bestLen = 0;
    uint32_t bestDist = 0;
    if (pos + kMatchMinLen > size) return 0;
    uint32_t avail = (uint32_t)std::min<size_t>(maxLen, size - pos);
    if (avail < kMatchMinLen) return 0;
    int32_t cand = prev[pos];
    size_t limit = pos > window ? pos - window : 0;
    const Byte* cur = data + pos;
    uint32_t quickBest = kMatchMinLen - 1;
    while (cand >= 0 && (size_t)cand >= limit && depth-- > 0) {
      const Byte* m = data + cand;
      if (quickBest < avail && m[quickBest] != cur[quickBest]) {
        cand = prev[cand];
        continue;
      }
      uint32_t len = 0;
      while (len < avail && m[len] == cur[len]) len++;
      if (len > bestLen) {
        bestLen = len;
        bestDist = (uint32_t)(pos - (size_t)cand);
        if (len >= avail) break;
        quickBest = len;
      }
      cand = prev[cand];
    }
    if (bestLen >= kMatchMinLen) {
      *distOut = bestDist;
      return bestLen;
    }
    return 0;
  }
};

struct LzmaEncoder {
  const Byte* in;
  size_t inSize;
  LzmaProps props;
  bool endMarker;

  ProbModels pm;
  LenProbs lenCoder, repLenCoder;
  RangeEnc re;
  MatchFinder mf;

  uint32_t state;
  uint32_t reps[4];

  uint32_t chainDepth;

  void EncodeLen(LenProbs& lc_, uint32_t len, uint32_t posState) {
    uint32_t sym = len - kMatchMinLen;
    if (sym < 8) {
      re.EncodeBit(lc_.choice, 0);
      re.EncodeTree(lc_.low[posState], 3, sym);
    } else if (sym < 16) {
      re.EncodeBit(lc_.choice, 1);
      re.EncodeBit(lc_.choice2, 0);
      re.EncodeTree(lc_.mid[posState], 3, sym - 8);
    } else {
      re.EncodeBit(lc_.choice, 1);
      re.EncodeBit(lc_.choice2, 1);
      re.EncodeTree(lc_.high, 8, sym - 16);
    }
  }

  void EncodeLiteral(uint32_t pos) {
    uint32_t prevByte = pos ? in[pos - 1] : 0;
    uint32_t litState = ((uint32_t)pos & ((1u << props.lp) - 1)) << props.lc;
    litState += prevByte >> (8 - props.lc);
    uint16_t* probs = &pm.lit[(size_t)litState * 0x300];
    uint32_t sym = in[pos];
    if (state >= 7) {
      // matched-literal mode
      uint32_t matchByte = in[pos - reps[0]];
      uint32_t m = 1;
      for (;;) {
        uint32_t matchBit = (matchByte >> 7) & 1;
        matchByte <<= 1;
        uint32_t bit = (sym >> 7) & 1;
        uint32_t idx = ((1 + matchBit) << 8) + m;
        re.EncodeBit(probs[idx], bit);
        m = (m << 1) | bit;
        sym <<= 1;
        if (matchBit != bit) break;
      }
      while (m < 0x100) {
        uint32_t bit = (sym >> 7) & 1;
        re.EncodeBit(probs[m], bit);
        m = (m << 1) | bit;
        sym <<= 1;
      }
    } else {
      uint32_t m = 1;
      for (int i = 7; i >= 0; i--) {
        uint32_t bit = (sym >> i) & 1;
        re.EncodeBit(probs[m], bit);
        m = (m << 1) | bit;
      }
    }
    state = state < 4 ? 0 : state < 10 ? state - 3 : state - 6;
  }

  void EncodeMatch(uint32_t pos, uint32_t len, uint32_t dist) {
    uint32_t posState = (uint32_t)pos & ((1u << props.pb) - 1);
    re.EncodeBit(pm.isMatch[state][posState], 1);
    re.EncodeBit(pm.isRep[state], 0);
    EncodeLen(lenCoder, len, posState);
    uint32_t slot = GetPosSlot(dist);
    re.EncodeTree(pm.posSlot[GetLenToPosState(len)], kNumPosSlotBits, slot);
    if (slot >= 4) {
      uint32_t footer = (slot >> 1) - 1;
      uint32_t base = (2 | (slot & 1)) << footer;
      uint32_t reduced = dist - base;
      if (slot < kEndPosModelIndex) {
        re.EncodeTreeRev(pm.specPos + base - slot, footer, reduced);
      } else {
        re.EncodeDirect(reduced >> kNumAlignBits, footer - kNumAlignBits);
        re.EncodeTreeRev(pm.posAlign, kNumAlignBits, reduced & (kAlignTableSize - 1));
      }
    }
    reps[3] = reps[2];
    reps[2] = reps[1];
    reps[1] = reps[0];
    reps[0] = dist + 1;
    state = state < 7 ? 7 : 10;
  }

  void EncodeRepMatch(uint32_t pos, uint32_t len, uint32_t idx) {
    uint32_t posState = (uint32_t)pos & ((1u << props.pb) - 1);
    re.EncodeBit(pm.isMatch[state][posState], 1);
    re.EncodeBit(pm.isRep[state], 1);
    if (idx == 0) {
      re.EncodeBit(pm.isRepG0[state], 0);
      re.EncodeBit(pm.isRep0Long[state][posState], len == 1 ? 0 : 1);
    } else {
      re.EncodeBit(pm.isRepG0[state], 1);
      uint32_t dist = reps[idx];
      if (idx == 1) {
        re.EncodeBit(pm.isRepG1[state], 0);
      } else {
        re.EncodeBit(pm.isRepG1[state], 1);
        re.EncodeBit(pm.isRepG2[state], idx - 2);
        if (idx == 3) reps[3] = reps[2];
        reps[2] = reps[1];
      }
      reps[1] = reps[0];
      reps[0] = dist;
    }
    if (len > 1) EncodeLen(repLenCoder, len, posState);
    state = len == 1 ? (state < 7 ? 9 : 11) : (state < 7 ? 8 : 11);
  }

  bool Encode() {
    pm.Init(props.lc, props.lp);
    lenCoder.Init();
    repLenCoder.Init();
    re.Init();
    state = 0;
    reps[0] = reps[1] = reps[2] = reps[3] = 1;
    uint32_t dictSize = props.dictSize;
    if (dictSize < 4096) dictSize = 4096;
    mf.Init(in, inSize, dictSize);

    size_t pos = 0;
    while (pos < inSize) {
      mf.Insert(pos);

      // check rep matches (rep0 cheapest, then rep1..3 for longer ones)
      uint32_t maxAvail = (uint32_t)std::min<size_t>(kMatchMaxLen, inSize - pos);
      uint32_t repLen = 0, repIdx = 0;
      for (uint32_t r = 0; r < 4 && maxAvail >= 1; r++) {
        uint32_t d = reps[r];
        if ((uint64_t)d > (uint64_t)pos) continue;
        const Byte* m = in + pos - d;
        uint32_t l = 0;
        while (l < maxAvail && m[l] == in[pos + l]) l++;
        if (l >= kMatchMinLen && l > repLen + (r == 0 ? 0 : 1)) {
          repLen = l;
          repIdx = r;
        }
      }
      // short rep0 (len 1) check
      bool shortRep = false;
      if (maxAvail >= 1 && reps[0] <= pos && in[pos - reps[0]] == in[pos]) {
        shortRep = true;
      }

      uint32_t mfLen = 0, mfDist = 0;
      uint32_t availForMf = (uint32_t)std::min<size_t>(kMatchMaxLen, inSize - pos);
      if (availForMf >= kMatchMinLen)
        mfLen = mf.Find(pos, availForMf, chainDepth, &mfDist);

      if (repLen >= mfLen && repLen >= kMatchMinLen) {
        EncodeRepMatch((uint32_t)pos, repLen, repIdx);
        for (uint32_t i = 1; i < repLen; i++) mf.Insert(pos + i);
        pos += repLen;
        continue;
      }
      if (mfLen >= kMatchMinLen) {
        EncodeMatch((uint32_t)pos, mfLen, mfDist - 1);
        for (uint32_t i = 1; i < mfLen; i++) mf.Insert(pos + i);
        pos += mfLen;
        continue;
      }
      if (shortRep) {
        EncodeRepMatch((uint32_t)pos, 1, 0);
        pos += 1;
        continue;
      }
      EncodeLiteral((uint32_t)pos);
      pos += 1;
    }

    if (endMarker) {
      uint32_t posState = (uint32_t)inSize & ((1u << props.pb) - 1);
      re.EncodeBit(pm.isMatch[state][posState], 1);
      re.EncodeBit(pm.isRep[state], 0);
      EncodeLen(lenCoder, kMatchMinLen, posState); // any length; decoder ignores
      re.EncodeTree(pm.posSlot[0], kNumPosSlotBits, (1u << kNumPosSlotBits) - 1);
      re.EncodeDirect(0x03FFFFFFu, 26);
      re.EncodeTreeRev(pm.posAlign, kNumAlignBits, kAlignTableSize - 1);
    }
    re.Flush();
    return true;
  }
};

} // namespace

bool LzmaEncode(const Byte* in, size_t inSize, ByteBuf& out,
                const LzmaProps& props, bool writeEndMarker) {
  if (props.lc < 0 || props.lc > 4 || props.lp < 0 || props.lp > 4 ||
      props.pb < 0 || props.pb > 4 || props.lc + props.lp > 4)
    return false;
  LzmaEncoder enc;
  enc.in = in;
  enc.inSize = inSize;
  enc.props = props;
  enc.endMarker = writeEndMarker;
  // chain depth scales loosely with dictionary size; greedy parsing needs no prices
  enc.chainDepth = 128;
  if (!enc.Encode()) return false;
  out = std::move(enc.re.buf);
  return true;
}

Byte Lzma2DictByteForSize(uint64_t size) {
  for (int b = 0; b <= 40; b++) {
    uint64_t dict = (uint64_t)(2 | (b & 1)) << (b / 2 + 11);
    if (dict >= size) return (Byte)b;
  }
  return 40;
}

ByteBuf Lzma2Encode(const Byte* in, uint64_t inSize, const LzmaProps& props, Byte dictProp) {
  (void)dictProp; // dictionary content is irrelevant: first chunk resets dict
  ByteBuf out;
  if (inSize == 0) {
    out.push_back(0);
    return out;
  }
  const uint32_t kMaxChunkUnpack = 1u << 20; // 21-bit field
  const uint32_t kMaxChunkPack = 0x10000;    // 16-bit field

  uint64_t pos = 0;
  bool first = true;
  while (pos < inSize) {
    uint32_t chunkSize = (uint32_t)std::min<uint64_t>(kMaxChunkUnpack, inSize - pos);
    const Byte* chunk = in + pos;

    ByteBuf packed;
    LzmaEncode(chunk, chunkSize, packed, props, false);

    bool useCompressed = packed.size() < chunkSize && packed.size() <= kMaxChunkPack;
    if (!useCompressed) {
      // store chunk uncompressed; must fit the 16-bit size field
      uint32_t stored = 0;
      while (stored < chunkSize) {
        uint32_t part = chunkSize - stored;
        if (part > 0x10000) part = 0x10000;
        out.push_back(first ? 0x01 : 0x02);
        first = false;
        uint32_t s = part - 1;
        out.push_back((Byte)(s >> 8));
        out.push_back((Byte)s);
        out.insert(out.end(), chunk + stored, chunk + stored + part);
        stored += part;
      }
    } else {
      // reset mode 2: state reset + new props (plus dict reset on first chunk)
      out.push_back(first ? (Byte)0xE0 : (Byte)0xA0);
      first = false;
      out.push_back(props.PropsByte());
      uint32_t u = chunkSize - 1;
      out.push_back((Byte)((u >> 16) & 0x1F));
      out.push_back((Byte)(u >> 8));
      out.push_back((Byte)u);
      uint32_t p = (uint32_t)packed.size() - 1;
      out.push_back((Byte)(p >> 8));
      out.push_back((Byte)p);
      out.insert(out.end(), packed.begin(), packed.end());
    }
    pos += chunkSize;
  }
  out.push_back(0);
  return out;
}

// Test harness: LZMA2-encode files, wrap into .xz container, write to /tmp/xztest/.
#include "Lzma.h"
#include <cstdio>
#include <cstring>
#include <string>

// xz-standard CRC32 (reflected, poly 0xEDB88320)
static uint32_t crc32(const Byte* p, size_t n, uint32_t c = 0) {
  static uint32_t tab[256];
  static bool init = false;
  if (!init) {
    for (uint32_t i = 0; i < 256; i++) {
      uint32_t v = i;
      for (int j = 0; j < 8; j++) v = (v >> 1) ^ (v & 1 ? 0xEDB88320u : 0);
      tab[i] = v;
    }
    init = true;
  }
  c = ~c;
  for (size_t i = 0; i < n; i++) c = tab[(c ^ p[i]) & 0xFF] ^ (c >> 8);
  return ~c;
}

static void put32le(ByteBuf& b, uint32_t v) {
  b.push_back((Byte)v); b.push_back((Byte)(v >> 8));
  b.push_back((Byte)(v >> 16)); b.push_back((Byte)(v >> 24));
}
static void putVarint(ByteBuf& b, uint64_t v) {
  do {
    Byte x = (Byte)(v & 0x7F);
    v >>= 7;
    b.push_back(v ? (Byte)(x | 0x80) : x);
  } while (v);
}

// Build a single-block .xz around an LZMA2 stream.
static ByteBuf buildXz(const ByteBuf& lzma2, const ByteBuf& raw, Byte dictProp) {
  ByteBuf xz;
  // stream header
  const Byte magic[] = {0xFD, '7', 'z', 'X', 'Z', 0x00};
  xz.insert(xz.end(), magic, magic + 6);
  Byte flags[2] = {0x00, 0x01}; // CRC32 check
  xz.push_back(flags[0]); xz.push_back(flags[1]);
  put32le(xz, crc32(flags, 2));

  // block header: size byte, flags 0x00, filter id 0x21, props size 1, props byte
  ByteBuf bh;
  bh.push_back(0); // placeholder for size
  bh.push_back(0x00);
  bh.push_back(0x21);
  bh.push_back(0x01);
  bh.push_back(dictProp);
  while ((bh.size() + 4) % 4 != 0) bh.push_back(0); // pad so that with CRC it's multiple of 4
  bh[0] = (Byte)((bh.size() + 4) / 4);
  uint32_t bhcrc = crc32(bh.data(), bh.size());
  xz.insert(xz.end(), bh.begin(), bh.end());
  put32le(xz, bhcrc);

  size_t blockStart = xz.size();
  xz.insert(xz.end(), lzma2.begin(), lzma2.end());
  while (xz.size() % 4 != 0) xz.push_back(0); // block padding
  uint32_t datacrc = crc32(raw.data(), raw.size());
  put32le(xz, datacrc); // check field

  uint64_t unpaddedSize = (xz.size() - blockStart) + bh.size() + 4;
  // unpadded size = block header size + compressed data size + check size (no padding)
  unpaddedSize = bh.size() + 4 + lzma2.size() + 4;

  // index
  ByteBuf idx;
  idx.push_back(0x00);
  putVarint(idx, 1); // record count
  putVarint(idx, unpaddedSize);
  putVarint(idx, raw.size());
  while ((idx.size() + 4) % 4 != 0) idx.push_back(0);
  uint32_t idxcrc = crc32(idx.data(), idx.size());
  size_t indexSize = idx.size() + 4;
  xz.insert(xz.end(), idx.begin(), idx.end());
  put32le(xz, idxcrc);

  // footer
  uint32_t backwdSize = (uint32_t)(indexSize / 4 - 1);
  Byte foot[6];
  foot[0] = (Byte)0; foot[1] = (Byte)(idxcrc >> 0); // placeholder, compute properly below
  // footer CRC covers backward size (4 bytes) + flags (2 bytes)
  Byte tmp[6];
  tmp[0] = (Byte)backwdSize; tmp[1] = (Byte)(backwdSize >> 8);
  tmp[2] = (Byte)(backwdSize >> 16); tmp[3] = (Byte)(backwdSize >> 24);
  tmp[4] = 0x00; tmp[5] = 0x01;
  put32le(xz, crc32(tmp, 6));
  (void)foot;
  xz.insert(xz.end(), tmp, tmp + 6);
  xz.push_back('Y'); xz.push_back('Z');
  return xz;
}

static bool readFile(const std::string& path, ByteBuf& out) {
  FILE* f = fopen(path.c_str(), "rb");
  if (!f) return false;
  fseek(f, 0, SEEK_END);
  long n = ftell(f);
  fseek(f, 0, SEEK_SET);
  out.resize(n);
  if (n && fread(out.data(), 1, n, f) != (size_t)n) { fclose(f); return false; }
  fclose(f);
  return true;
}

static bool writeFile(const std::string& path, const ByteBuf& d) {
  FILE* f = fopen(path.c_str(), "wb");
  if (!f) return false;
  bool ok = d.empty() || fwrite(d.data(), 1, d.size(), f) == d.size();
  fclose(f);
  return ok;
}

int main(int argc, char** argv) {
  if (argc < 4) {
    fprintf(stderr, "usage: %s <infile> <out.xz> <lc lp pb dictbyte>\n", argv[0]);
    return 1;
  }
  ByteBuf raw;
  if (!readFile(argv[1], raw)) { fprintf(stderr, "cannot read %s\n", argv[1]); return 1; }
  LzmaProps props;
  if (argc >= 8) {
    props.lc = atoi(argv[4]); props.lp = atoi(argv[5]); props.pb = atoi(argv[6]);
  }
  Byte dictProp = argc >= 8 ? (Byte)atoi(argv[7]) : Lzma2DictByteForSize(raw.size());
  props.dictSize = (uint32_t)(2 | (dictProp & 1)) << (dictProp / 2 + 11);
  ByteBuf lzma2 = Lzma2Encode(raw.data(), raw.size(), props, dictProp);
  ByteBuf xz = buildXz(lzma2, raw, dictProp);
  if (!writeFile(argv[2], xz)) { fprintf(stderr, "cannot write %s\n", argv[2]); return 1; }
  printf("in=%zu lzma2=%zu xz=%zu\n", raw.size(), lzma2.size(), xz.size());
  return 0;
}

