319	
320	bool LzmaDecode(const Byte* in, size_t inSize, Byte* out, uint64_t outSize,
321	                const LzmaProps& props, size_t* inConsumed) {
322	  if (props.lc > 8 || props.lp > 4 || props.pb > 4 ||
323	      props.lc < 0 || props.lp < 0 || props.pb < 0)
324	    return false;
325	  LzmaDecoder dec;
326	  if (!dec.SetProps(props.lc, props.lp, props.pb)) return false;
327	  dec.ResetState();
328	  dec.SetWindow(out, 0, 0);
329	  bool marker = (outSize == UINT64_MAX);
330	  size_t consumed = 0;
331	  uint64_t produced = 0;
332	  if (!dec.Run(in, inSize, marker ? UINT64_MAX : outSize, marker,
333	               &consumed, &produced))
334	    return false;
335	  if (!marker && produced != outSize) return false;
336	  if (inConsumed) *inConsumed = consumed;
337	  return true;
338	}
339	
340	bool Lzma2Decode(const Byte* in, size_t inSize, Byte* out, uint64_t outSize, Byte dictProp) {
341	  (void)dictProp; // dict size is irrelevant: matches never cross a dict reset
342	  LzmaDecoder dec;
343	  dec.SetWindow(out, 0, 0);
344	  size_t pos = 0;
345	  uint64_t outPos = 0, winStart = 0;
346	  bool dictStarted = false;
347	  bool hasProps = false;
348	
349	  while (pos < inSize) {
350	    Byte ctrl = in[pos++];
351	    if (ctrl == 0)
352	      break; // end of LZMA2 stream
353	    if (ctrl >= 0x80) {
354	      // ---- compressed chunk
355	      if (pos + 4 > inSize) return false;
356	      uint32_t unpack = (((uint32_t)ctrl & 0x1F) << 16) +
357	                        ((uint32_t)in[pos] << 8) + in[pos + 1] + 1;
358	      uint32_t pack = ((uint32_t)in[pos + 2] << 8) + in[pos + 3] + 1;
359	      pos += 4;
360	      int reset = (ctrl >> 5) & 3;
361	      if (reset >= 2) {
362	        // new properties byte follows
363	        if (pos >= inSize) return false;
364	        Byte b = in[pos++];
365	        if (b > (Byte)((4 * 5 + 4) * 9 + 4)) return false; // lc<=4 in LZMA2
366	        int lc = b % 9, r = b / 9, lp = r % 5, pb = r / 5;
367	        if (!dec.SetProps(lc, lp, pb)) return false;
368	        hasProps = true;
369	      }
370	      if (!hasProps) return false;
371	      if (reset >= 1)
372	        dec.ResetState();
373	      if (reset == 3) {
374	        winStart = outPos; // dictionary reset
375	        dictStarted = true;
376	      }
377	      if (!dictStarted) return false; // first chunk must reset the dictionary
378	      if (outSize - outPos < unpack) return false;
379	      if (inSize - pos < pack) return false;
380	      dec.SetWindow(out, outPos, winStart);
381	      size_t consumed = 0;
382	      uint64_t produced = 0;
383	      if (!dec.Run(in + pos, pack, unpack, false, &consumed, &produced))
384	        return false;
385	      if (produced != outPos + unpack) return false;
386	      pos += pack; // trust the chunk header for the packed size
387	      outPos += unpack;
388	    } else if (ctrl <= 2) {
389	      // ---- uncompressed chunk (1 = dict reset, 2 = no reset)
390	      if (pos + 2 > inSize) return false;
391	      uint32_t size = ((uint32_t)in[pos] << 8) + in[pos + 1] + 1;
392	      pos += 2;
393	      if (ctrl == 1) {
394	        winStart = outPos;
395	        dictStarted = true;
396	      }
397	      if (!dictStarted) return false;
398	      if (outSize - outPos < size) return false;
399	      if (inSize - pos < size) return false;
400	      memcpy(out + outPos, in + pos, size);
401	      pos += size;
402	      outPos += size;
403	    } else {
404	      return false; // 0x03..0x7F are reserved
405	    }
406	  }
407	  return outPos == outSize;
408	}

