static inline uint32_t GetPosSlot(uint32_t dist) {
  // dist is (distance - 1). Slots 0..3 map directly; above that each power-of-two
  // band contributes two slots, selected by the second-highest bit.
  if (dist < 4) return dist;
  uint32_t i = 31;
#if defined(__GNUC__)
  i = 31u - (uint32_t)__builtin_clz(dist);
#else
  while (!((dist >> i) & 1)) i--;
#endif
  return (i << 1) | ((dist >> (i - 1)) & 1);
}

