static bool readFile(const char* p, ByteBuf& o){FILE*f=fopen(p,"rb");if(!f)return false;fseek(f,0,SEEK_END);long n=ftell(f);fseek(f,0,SEEK_SET);o.resize(n);if(n&&fread(o.data(),1,n,f)!=(size_t)n){fclose(f);return false;}fclose(f);return true;}
int main(int argc,char**argv){
  ByteBuf raw; if(!readFile(argv[1],raw))return 1;
  LzmaProps pr;
  if(argc>2){pr.lc=atoi(argv[2]);pr.lp=atoi(argv[3]);pr.pb=atoi(argv[4]);}
  Byte dp = Lzma2DictByteForSize(raw.size());
  pr.dictSize = (uint32_t)(2|(dp&1)) << (dp/2+11);
  ByteBuf enc = Lzma2Encode(raw.data(),raw.size(),pr,dp);
  ByteBuf dec(raw.size());
  bool ok = Lzma2Decode(enc.data(),enc.size(),dec.data(),raw.size(),dp);
  printf("in=%zu lzma2=%zu dictByte=%d %s\n",raw.size(),enc.size(),dp,(ok&&dec==raw)?"OK":(ok?"MISMATCH":"FAIL"));
  return 0;
}
