import random,subprocess
random.seed(99)
fails=0
for i in range(60):
    n=random.choice([0,1,2,3,5,17,100,1000,4096,65535,65536,65537,70000,200000,300000])
    mode=random.randrange(4)
    if mode==0: b=bytes(random.randrange(256) for _ in range(n))
    elif mode==1: b=bytes(n)
    elif mode==2:
        unit=bytes(random.randrange(256) for _ in range(random.randrange(1,20) or 1))
        b=(unit*(n//max(1,len(unit))+1))[:n]
    else:
        b=bytearray()
        while len(b)<n:
            if b and random.random()<0.5:
                s=random.randrange(len(b)); l=min(random.randrange(1,300),n-len(b))
                b+=b[s:s+l]
            else:
                b+=bytes([random.randrange(256)])
        b=bytes(b[:n])
    open('/tmp/fz.bin','wb').write(b)
    r=subprocess.run(['/tmp/rt3','/tmp/fz.bin'],capture_output=True,text=True)
    if ' OK' not in r.stdout: fails+=1; print("FUZZFAIL",i,n,mode,r.stdout,r.stderr)
print("fuzz done, fails=",fails)
